 unAction(action){const p=this.unPreview(action);if(p.blocked.length)return this.result(false,p.blocked[0]);this.pay(p.cost);const u=this.s.un,m=this.s.metrics,d=UNITED_NATIONS.actions[action];if(action==='liaison'){u.contact=2;u.trust=clamp(u.trust+12,-100,100);u.knowledge=clamp(u.knowledge+10);u.suspicion=clamp(u.suspicion+4);u.memory.unshift('A discreet mission channel was opened.');}if(action==='brief'){u.briefed=true;u.contact=Math.max(u.contact,3);u.trust=clamp(u.trust+16,-100,100);u.knowledge=clamp(u.knowledge+18);u.suspicion=clamp(u.suspicion+4);u.legitimacy=clamp(u.legitimacy+10);m.trust=clamp(m.trust+2);u.memory.unshift('A multinational scientific panel received a bounded briefing.');}if(action==='network'){u.infiltration=clamp(u.infiltration+24);u.trust=clamp(u.trust+6,-100,100);u.legitimacy=clamp(u.legitimacy+5);u.suspicion=clamp(u.suspicion+7);u.knowledge=clamp(u.knowledge+4);this.s.cooldowns.unNetwork=this.s.day+730;u.memory.unshift('Embedded careers created durable institutional access.');}if(action==='framework'){u.framework=true;u.contact=4;u.trust=clamp(u.trust+12,-100,100);u.dependence=clamp(u.dependence+10);u.knowledge=clamp(u.knowledge+18);u.suspicion=clamp(u.suspicion-6);u.legitimacy=clamp(u.legitimacy+28);m.trust=clamp(m.trust+4);m.panic=clamp(m.panic-2);u.memory.unshift('A classified inspection and deconfliction framework was accepted.');}if(action==='mandate'){u.contact=5;u.trust=clamp(u.trust+12,-100,100);u.knowledge=100;u.hostility=clamp(u.hostility-8);u.legitimacy=clamp(u.legitimacy+25);this.s.open=true;this.s.flags.unMandate=true;m.belief=clamp(m.belief+18);m.coherence=clamp(m.coherence+18);m.panic=clamp(m.panic+5);m.trust=clamp(m.trust+10);this.s.doctrine.autonomy=clamp(this.s.doctrine.autonomy+5);this.addEvidence('United Nations disclosure dossier','840',8,'document',true,'disclosure');u.memory.unshift('The global forum introduced the Network under an agreed disclosure mandate.');}u.memory=u.memory.slice(0,10);this.log(`United Nations: ${d.name}.`,'diplomacy');this.notice(`United Nations · ${d.name}`);return this.result(true,d.name+' completed');}
 disclosurePreview(mode='authority'){const blocked=[],cost={intel:35,influence:45,energy:25},c=this.control();if(mode!=='authority')blocked.push('Unknown disclosure posture');if(this.s.open)blocked.push('The Network is already openly established');if(this.year<2017)blocked.push('Available from 2017');if(!this.tech('human5'))blocked.push('Research Treaty Architecture');if(c.total<55)blocked.push('Global control must reach 55');if(c.regions<4)blocked.push('Presence across 4 regions is required');if(this.s.doctrine.coercion<8)blocked.push('Coercion must reach 8');if(this.countries().filter(x=>x.contact>=3).length<2)blocked.push('Maintain limited contact with 2 countries');blocked.push(...this.shortages(cost));return {cost,blocked};}
 disclose(mode='authority'){const p=this.disclosurePreview(mode);if(p.blocked.length)return this.result(false,p.blocked[0]);this.pay(p.cost);const s=this.s,m=s.metrics;s.open=true;s.flags.declaredAuthority=true;s.doctrine.coercion=clamp(s.doctrine.coercion+12);m.belief=clamp(m.belief+20);m.coherence=clamp(m.coherence+22);m.panic=clamp(m.panic+12);m.trust=clamp(m.trust-8);for(const c of this.countries().filter(c=>c.contact>0||c.knowledge>0)){c.knowledge=clamp(c.knowledge+20);c.hostility=clamp(c.hostility+8);c.suspicion=clamp(c.suspicion+8);}s.un.contact=Math.max(s.un.contact,2);s.un.knowledge=100;s.un.suspicion=clamp(s.un.suspicion+15);s.un.hostility=clamp(s.un.hostility+12);s.un.trust=clamp(s.un.trust-8,-100,100);this.addEvidence('Network authority declaration','840',15,'broadcast',true,'disclosure');this.log('The Network declared an open administrative presence. Secrecy ended; the campaign did not.','milestone');this.notice('Open presence established. Humanity is responding.','warning');return this.result(true,'The Network is now openly established');}
