 marketPrice(k,buy=true){return (this.s.prices[k]||0)*(buy?1.08:.87)*(1+this.s.footprint/1200);}
 trade(k,amount,buy=true){if(!MATERIAL_PRICE[k]||!Number.isInteger(amount)||amount<1||amount>100)return this.result(false,'Invalid order');if(!this.legal())return this.result(false,'Establish a front company or resource agreement first');const cost=buy?{capital:this.marketPrice(k,true)*amount}:{[k]:amount};if(buy&&this.s.resources[k]+amount>this.capacity(k)+1e-8)return this.result(false,'Not enough storage space');if(!this.pay(cost))return this.result(false,this.shortages(cost)[0]);this.gain(buy?{[k]:amount}:{capital:this.marketPrice(k,false)*amount});const cover=(this.tech('human2')?.75:1)/(1+this.moduleCount('logistics')*.12);this.s.footprint=clamp(this.s.footprint+amount*.7*cover,0,200);this.s.prices[k]=clamp(this.s.prices[k]*(buy?1+amount*.001:1-amount*.0005),MATERIAL_PRICE[k]*.6,MATERIAL_PRICE[k]*1.7);return this.result(true,`${buy?'Purchased':'Sold'} ${amount} ${RESOURCES[k].name.toLowerCase()}`);}
 upgradeFront(id){const f=this.s.fronts.find(f=>f.id===id);if(!f)return this.result(false,'Company not found');if(f.level>=5)return this.result(false,'Maximum company scale reached');const cost={capital:25*f.level,influence:5*f.level};if(!this.pay(cost))return this.result(false,this.shortages(cost)[0]);f.level++;f.cover=clamp(f.cover+8);this.s.footprint=clamp(this.s.footprint+8,0,200);return this.result(true,`${f.name} expanded to level ${f.level}`);}
