  if(action==='misdirect'){this.s.metrics.coherence=clamp(this.s.metrics.coherence-6);this.s.metrics.belief=clamp(this.s.metrics.belief+4);this.s.noiseUses++;this.s.pattern=clamp(this.s.pattern+4);}
