  if(id==='shepherd'){add('Welfare at least 80',s.doctrine.welfare>=80);add('Six completed relief efforts',(s.stats.relief||0)>=6);add('Four active bases',s.bases.length>=4);add('Three trusted regions',c.trusted>=3);}
